import { describe, it, expect } from "vitest";
import { readFileSync } from "fs";
import { fileURLToPath } from "url";
import { BUILTIN_DEFINITIONS } from "../builtins";

// builtins.generated.json is a plain-JSON mirror of BUILTIN_DEFINITIONS so the
// plain-node seed script (prisma/seed.js) can read the builtins without TS
// tooling. It is generated by `npx tsx scripts/generate-builtins-json.ts` and
// must never be hand-edited — this test fails when the mirror drifts from the
// source of truth.
describe("generated mirror parity", () => {
  it("builtins.generated.json matches BUILTIN_DEFINITIONS exactly", () => {
    const mirrorPath = fileURLToPath(new URL("../builtins.generated.json", import.meta.url));
    const mirror = readFileSync(mirrorPath, "utf8");
    expect(mirror).toBe(JSON.stringify(BUILTIN_DEFINITIONS, null, 2) + "\n");
  });
});
